41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	    private static final String ERROR_DUPLICATE_TELEPHONE = "An owner with the same telephone already exists";
57	    private static final String ERROR_DUPLICATE_HOUSEHOLD = "An owner with the same last name and address already exists";
58	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city already contains the maximum number of owners";
59	    private static final String ERROR_DAILY_LIMIT_EXCEEDED = "The maximum number of owners that may be created today has been reached";
60	    private static final String ERROR_INVALID_TELEPHONE = "The supplied telephone number is not a valid E.164 number";
61	    private static final String ERROR_INVALID_ADDRESS = "The supplied address is blank after normalization";
62	
63	    /**
64	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
65	     * class.
66	     *
67	     * @param e     Object referring to the thrown exception.
68	     * @param status HTTP response status.
69	     * @param url URL request.
70	     */
71	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
72	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
73	        problemDetail.setType(URI.create(url.toString()));
74	        problemDetail.setTitle(e.getClass().getSimpleName());
